<?php if ( ! defined( 'ABSPATH' ) ) { exit; }
$user = $args['user']; $type = 'analyst-request' === $args['view'] ? 'analyst' : 'situation';
$application = Revayat_Companion_Member_Applications::latest( $user->ID, $type ); $state = Revayat_Companion_Member_Applications::state( $application );
$data = $application ? (array) get_post_meta( $application->ID, '_rv_payload', true ) : Revayat_Companion_Member_Profile::get( $user->ID );
$documents = $application ? (array) get_post_meta( $application->ID, '_rv_documents', true ) : array();
