<section class="rv-member-card"><h2><?php echo 'analyst' === $type ? 'مسیر عضویت در شبکه تحلیلگران' : 'مدارک و شرایط دسترسی ویژه'; ?></h2><p><?php echo 'analyst' === $type ? 'حوزه تخصص و معرفی حرفه‌ای شما بررسی می‌شود. نتیجه و توضیحات بررسی در همین صفحه و اعلان‌های پنل نمایش داده می‌شود. این درخواست، دسترسی اتاق وضعیت ایجاد نمی‌کند.' : 'نام کامل، کد ملی، عکس پرسنلی و تصویر کارت ملی برای بررسی لازم‌اند. این مدارک عمومی نمی‌شوند و عکس پرسنلی جایگزین تصویر پروفایل شما نخواهد شد.'; ?></p><ol class="rv-member-steps"><li>تکمیل اطلاعات</li><li>ارسال برای بررسی</li><li>اعلام نتیجه</li></ol><p><span class="rv-member-badge"><?php echo esc_html( Revayat_Companion_Member_Applications::labels()[ $state ] ); ?></span></p>
<?php if ( $blocked ) : ?><p class="rv-member-notice">دریافت مدارک هنوز فعال نشده است. پس از تعیین مدت نگهداری و آماده‌سازی فضای خصوصی، امکان ارسال فراهم می‌شود.</p><?php endif; ?>
<?php if ( $application && get_post_meta( $application->ID, '_rv_feedback', true ) ) : ?><div class="rv-member-notice"><strong>توضیح بررسی</strong><p><?php echo esc_html( get_post_meta( $application->ID, '_rv_feedback', true ) ); ?></p></div><?php endif; ?>
<?php if ( 'approved' === $state ) : ?><a class="rv-member-button" href="<?php echo esc_url( 'analyst' === $type ? home_url( '/dashboard/?view=note-edit' ) : get_post_type_archive_link( 'situation_room' ) ); ?>"><?php echo 'analyst' === $type ? 'نوشتن یادداشت' : 'ورود به اتاق وضعیت'; ?></a><?php endif; ?></section>
<?php if ( $editable && ! $blocked ) : ?><form class="rv-member-card rv-member-form" data-rv-form data-dirty-guard method="post" enctype="multipart/form-data" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="revayat_member_application"><?php wp_nonce_field( 'rv_application', 'rv_nonce' ); ?><input type="hidden" name="type" value="<?php echo esc_attr( $type ); ?>"><input type="hidden" name="version" value="<?php echo esc_attr( $application ? get_post_meta( $application->ID, '_rv_version', true ) : 0 ); ?>">
<div class="rv-member-fields"><label>نام و نام خانوادگی<input name="full_name" maxlength="160" value="<?php echo esc_attr( $data['full_name'] ?? '' ); ?>" required></label>
<?php if ( 'analyst' === $type ) : ?><?php foreach ( array( 'role_title' => 'عنوان شغلی (اختیاری)', 'organization' => 'سازمان (اختیاری)', 'expertise' => 'حوزه تخصصی', 'sample_url' => 'پیوند نمونه تحلیل (اختیاری)' ) as $key => $label ) : ?><label><?php echo esc_html( $label ); ?><input name="<?php echo esc_attr( $key ); ?>" value="<?php echo esc_attr( $data[ $key ] ?? '' ); ?>" <?php echo 'expertise' === $key ? 'required' : ''; ?> type="<?php echo 'sample_url' === $key ? 'url' : 'text'; ?>" maxlength="500"></label><?php endforeach; ?><label class="rv-span-all">معرفی حرفه‌ای و سوابق<textarea name="bio" required minlength="30" maxlength="3000" rows="7"><?php echo esc_textarea( $data['bio'] ?? '' ); ?></textarea></label>
<?php else : ?><label>کد ملی<input name="national_id" inputmode="numeric" maxlength="10" data-digits autocomplete="off"><small><?php echo ! empty( $documents ) ? 'اگر تغییر نکرده، این فیلد را خالی بگذارید.' : '۱۰ رقم؛ صفر ابتدای کد را حفظ کنید.'; ?></small></label><?php foreach ( array( 'portrait' => 'عکس پرسنلی', 'national_card' => 'تصویر کارت ملی' ) as $field => $label ) : ?><label><?php echo esc_html( $label ); ?><input type="file" name="<?php echo esc_attr( $field ); ?>" accept="image/jpeg,image/png,image/webp"><small>JPG، PNG یا WebP؛ حداکثر ۵ مگابایت. <?php echo ! empty( $documents[ $field ] ) ? 'فایل قبلی ثبت شده؛ انتخاب فایل تازه آن را جایگزین می‌کند.' : ''; ?></small></label><?php endforeach; ?><label class="rv-span-all">دلیل درخواست (اختیاری)<textarea name="reason" maxlength="500" rows="4"><?php echo esc_textarea( $data['reason'] ?? '' ); ?></textarea></label><p class="rv-span-all">مدت نگهداری مدارک پس از تصمیم: <?php echo esc_html( revayat_en2fa( get_option( 'revayat_document_retention_days' ) ) ); ?> روز؛ پیش‌نویس رهاشده: <?php echo esc_html( revayat_en2fa( get_option( 'revayat_document_draft_days' ) ) ); ?> روز. سابقه تصمیم بدون تصویر باقی می‌ماند.</p><?php endif; ?></div>
<label class="rv-member-check"><input type="checkbox" name="consent" value="1">صحت اطلاعات و <?php echo 'analyst' === $type ? 'نمایش اطلاعات حرفه‌ای پس از تأیید را می‌پذیرم.' : 'استفاده خصوصی از مدارک برای بررسی این درخواست با مدت نگهداری اعلام‌شده را می‌پذیرم.'; ?></label><p data-form-status role="status" hidden></p><div class="rv-member-actions"><button class="rv-member-button" name="mode" value="submit">ارسال برای بررسی</button><button class="rv-member-secondary" name="mode" value="draft" formnovalidate>ذخیره پیش‌نویس</button></div></form><?php endif; ?>
<?php if ( $application ) : ?><section class="rv-member-card"><h2>تاریخچه درخواست</h2><ol><?php foreach ( get_post_meta( $application->ID, '_rv_history', false ) as $event ) : ?><li><strong><?php echo esc_html( Revayat_Companion_Member_Applications::labels()[ $event['to'] ] ?? '' ); ?></strong> — <?php echo esc_html( $event['at'] ); ?><?php if ( $event['reason'] ) : ?><p><?php echo esc_html( $event['reason'] ); ?></p><?php endif; ?></li><?php endforeach; ?></ol><?php if ( in_array( $state, array( 'draft', 'pending', 'needs_changes' ), true ) ) : ?><form data-rv-form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'rv_application', 'rv_nonce' ); ?><input type="hidden" name="action" value="revayat_member_application"><input type="hidden" name="type" value="<?php echo esc_attr( $type ); ?>"><input type="hidden" name="version" value="<?php echo esc_attr( get_post_meta( $application->ID, '_rv_version', true ) ); ?>"><input type="hidden" name="mode" value="withdraw"><p data-form-status role="status" hidden></p><button class="rv-member-secondary">انصراف از درخواست</button></form><?php endif; ?></section><?php endif; ?>
